import sys
from datetime import datetime, timedelta
from collections import defaultdict


def minutes(text):
    h, m = text.split(":")
    return int(h) * 60 + int(m)


def hm(total_minutes):
    hours = total_minutes // 60
    minutes = total_minutes % 60
    return f"{hours}:{minutes:02d}"


def main():
    target = {}
    weeks = defaultdict(int)
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if parts[0] == "target":
            name = parts[1]
            target_time = minutes(parts[2])
            target[name] = target_time
            continue
        if len(parts) != 4:
            continue
        name, date_str, start_str, end_str = parts
        try:
            date = datetime.strptime(date_str, "%Y-%m-%d")
        except ValueError:
            continue
        try:
            start = datetime.strptime(start_str, "%H:%M").time()
            end = datetime.strptime(end_str, "%H:%M").time()
        except ValueError:
            continue
        # Compute shift duration
        start_dt = datetime.combine(date, start)
        end_dt = datetime.combine(date, end)
        if end_dt < start_dt:
            end_dt += timedelta(days=1)
        duration = (end_dt - start_dt).total_seconds() / 60
        week = date.isocalendar()[1]  # ISO week number
        year = date.isocalendar()[0]
        week_str = f"{year}-W{week:02d}"
        weeks[(name, week_str)] += duration

    # Compute results
    balance = defaultdict(timedelta)
    for (name, week_str), worked in sorted(weeks.items()):
        target_time = target.get(name, 40 * 60)
        diff = worked - target_time
        sign = "+" if diff >= 0 else "-"
        print(f"{name} {week_str} {hm(worked)} {sign}{hm(abs(diff))}")
        balance[name] += diff

    # Print overtime summary
    for name in sorted(balance):
        total_overtime = balance[name]
        if total_overtime > timedelta(0):
            print(f"{name} overtime {hm(total_overtime)}")


if __name__ == "__main__":
    main()
